import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../..');
const read = p => fs.readFileSync(path.join(root, p), 'utf8');
const esc = v => String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const code = (s, lang='ตัวอย่าง') => `<div class="code"><div class="code-head"><span>${esc(lang)}</span><button type="button" class="copy">คัดลอก</button></div><pre><code>${esc(s.trim())}</code></pre></div>`;
const table = (heads, rows) => `<div class="table-wrap" tabindex="0" role="region" aria-label="ตาราง ${esc(heads[0])}"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note = (title, text) => `<aside class="note"><strong>${title}</strong><p>${text}</p></aside>`;
const list = items => `<ul>${items.map(s=>`<li>${s}</li>`).join('')}</ul>`;
const steps = items => `<ol class="steps">${items.map(([t,s])=>`<li><strong>${t}</strong><p>${s}</p></li>`).join('')}</ol>`;
const sources = (...paths) => `<p class="sources">อ้างอิง: ${paths.map(p=>`<a href="../../${p}">${p}</a>`).join(' · ')}</p>`;
const sections = [];
function section(id,title,kicker,body){sections.push({id,title,kicker,body});}
const contracts = read('web/admin/src/api/operations.ts');
const ops = [...contracts.matchAll(/"([a-z_]+)": \{ permission: "([A-Za-z]+)", availableToAi: (true|false) \}/g)].map(m=>({name:m[1],permission:m[2],ai:m[3]==='true'}));
const types = Object.fromEntries([...contracts.matchAll(/export type (\w+) = ([\s\S]*?);\r?\n/g)].map(m=>[m[1],m[2]+';']));
const bindings = Object.fromEntries([...contracts.matchAll(/"([a-z_]+)": \{ arguments: (\w+); result: (\w+) \}/g)].map(m=>[m[1],[m[2],m[3]]]));
const aiCount = ops.filter(o=>o.ai).length;
